/**
 * @returns {Promise.<void>}
 */
export async function JS_ScrollToUserMessageIfAtBottom() {
	// BEGIN USER CODE
      const container = document.querySelector('.messages-container');                                                                                                                                                                           
      if (container) {                                                                                                                                                                                                                           
          // Check if user was at bottom using the class                                                                                                                                                                                         
          const wasAtBottom = !container.classList.contains('not-at-bottom');                                                                                                                                                                    
                                                                                                                                                                                                                                                 
          if (wasAtBottom) {                                                                                                                                                                                                                     
              // Scroll to bottom to show the user's message                                                                                                                                                                                     
              container.scrollTop = container.scrollHeight;                                                                                                                                                                                      
              console.debug('Scrolled to user message');                                                                                                                                                                                           
          }                                                                                                                                                                                                                                      
      }                                                                                                                                                                                                                                          
	// END USER CODE
}
